<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { guardarItem, listarItems, type CatalogoItem, type GrupoOption, type ItemLogistico } from '../services/items'
const rows=ref<ItemLogistico[]>([]),groups=ref<GrupoOption[]>([]),units=ref<CatalogoItem[]>([]),summary=reactive({materiales:0,activos:0,servicios:0,sin_stock:0}),criterio=ref(''),page=ref(1),lastPage=ref(1),total=ref(0),loading=ref(false),saving=ref(false),error=ref(''),success=ref(''),modal=ref(false),editing=ref<number|null>(null),tab=ref<'general'|'technical'>('general'),photo=ref<File|null>(null),preview=ref('')
const form=reactive({nombre:'',grupo_id:0,subgrupo_id:0,unidad_id:0,uso_comun:false,stock_minimo:undefined as number|undefined,stock_maximo:undefined as number|undefined,lote_economico:undefined as number|undefined,punto_reposicion:undefined as number|undefined,consumo_promedio:undefined as number|undefined,remove_image:false})
const subgroups=computed(()=>groups.value.find(x=>x.id===form.grupo_id)?.subgrupos||[]),selectedGroup=computed(()=>groups.value.find(x=>x.id===form.grupo_id))
async function load(next=1){page.value=next;loading.value=true;error.value='';try{const r=await listarItems(criterio.value,next);rows.value=r.data;groups.value=r.grupos;units.value=r.unidades;total.value=r.total;lastPage.value=r.last_page;Object.assign(summary,r.resumen)}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(item?:ItemLogistico){editing.value=item?.id||null;Object.assign(form,{nombre:item?.nombre||'',grupo_id:item?.grupo_id||0,subgrupo_id:item?.subgrupo_id||0,unidad_id:item?.unidad_id||0,uso_comun:item?.uso_comun||false,stock_minimo:item?.stock_minimo,stock_maximo:item?.stock_maximo,lote_economico:item?.lote_economico,punto_reposicion:item?.punto_reposicion,consumo_promedio:item?.consumo_promedio,remove_image:false});photo.value=null;preview.value=item?.imagen_url||'';tab.value='general';modal.value=true}
function groupChanged(){form.subgrupo_id=0}
function choosePhoto(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/bmp'].includes(file.type)){error.value='Solo se admiten imágenes JPEG, PNG o BMP.';return}photo.value=file;preview.value=URL.createObjectURL(file);form.remove_image=false}
function removePhoto(){photo.value=null;preview.value='';form.remove_image=true}
function validate(){if(!form.grupo_id||!form.subgrupo_id)return 'Seleccione un grupo y subgrupo válidos.';if(form.nombre.trim().length<5)return 'El nombre debe tener al menos 5 caracteres.';if(!form.unidad_id)return 'Seleccione la unidad de medida.';const nums=[form.stock_minimo,form.stock_maximo,form.lote_economico,form.punto_reposicion];if(nums.some(x=>x!==undefined&&x<0))return 'Los parámetros de inventario no pueden ser negativos.';if(form.stock_minimo!==undefined&&form.stock_maximo!==undefined&&form.stock_minimo>form.stock_maximo)return 'El stock mínimo no puede superar al máximo.';return ''}
async function save(){const issue=validate();if(issue){error.value=issue;return}const data=new FormData();Object.entries(form).forEach(([key,value])=>{if(value!==undefined)data.append(key,String(value))});if(photo.value)data.append('fotografia',photo.value);saving.value=true;try{await guardarItem(editing.value,data);modal.value=false;success.value=`Ítem ${editing.value?'actualizado':'registrado'} correctamente.`;await load(editing.value?page.value:1)}catch(e){error.value=message(e)}finally{saving.value=false}}
const number=(v=0)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v),message=(e:unknown)=>e instanceof Error?e.message:'No se pudo completar la operación.';onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Administración / Logística / Ítems</nav><header class="hero"><div class="mark">IT</div><div><small>MIA · CATÁLOGO LOGÍSTICO</small><h1>Ítems</h1><p>Administra materiales, activos y servicios utilizados en abastecimiento.</p></div><b>{{total}} ítems</b><button @click="open()">+ Registrar ítem</button></header><p v-if="success" class="flash success">✓ {{success}}</p><p v-if="error" class="flash">{{error}}</p><section class="metrics"><article><small>MATERIALES</small><b>{{summary.materiales}}</b></article><article><small>ACTIVOS</small><b>{{summary.activos}}</b></article><article><small>SERVICIOS</small><b>{{summary.servicios}}</b></article><article class="bad"><small>SIN STOCK</small><b>{{summary.sin_stock}}</b></article></section><section class="filters"><input v-model.trim="criterio" placeholder="Buscar por ítem, grupo o subgrupo" @keyup.enter="load(1)"><button @click="load(1)">Buscar</button><button class="soft" @click="criterio='';load(1)">Limpiar</button></section>
<section class="table-card"><header><div><small>CATÁLOGO</small><h2>Lista de ítems</h2></div><b>{{total}} resultados</b></header><div v-if="loading" class="empty">Cargando ítems…</div><div v-else-if="!rows.length" class="empty">No se encontraron ítems.</div><div v-else class="scroll"><table><thead><tr><th>Imagen</th><th>Nombre</th><th>Grupo</th><th>Subgrupo</th><th>Tipo</th><th>Unidad</th><th>Stock</th><th></th></tr></thead><tbody><tr v-for="item in rows" :key="item.id"><td><img v-if="item.imagen_url" :src="item.imagen_url" alt=""><div v-else class="no-image">📦</div></td><td><b>{{item.nombre}}</b><span v-if="item.uso_comun" class="common">USO COMÚN</span></td><td>{{item.grupo}}</td><td>{{item.subgrupo}}</td><td><span class="family" :class="item.familia">{{item.familia_nombre}}</span></td><td>{{item.unidad}}</td><td><span v-if="item.familia==='m'" :class="(item.saldo||0)>0?'stock':'no-stock'">{{number(item.saldo)}}</span><span v-else>—</span></td><td><button class="link" @click="open(item)">Modificar</button></td></tr></tbody></table></div><footer v-if="lastPage>1"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{lastPage}}</span><button :disabled="page>=lastPage" @click="load(page+1)">Siguiente</button></footer></section>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="dialog" @submit.prevent="save"><header><div><small>FICHA DEL ÍTEM</small><h2>{{editing?'Editar':'Registrar'}} ítem</h2></div><button type="button" @click="modal=false">×</button></header><nav class="tabs"><button type="button" :class="{active:tab==='general'}" @click="tab='general'">Datos generales</button><button type="button" :class="{active:tab==='technical'}" @click="tab='technical'">Parámetros técnicos</button></nav><div v-if="tab==='general'" class="grid"><label>Grupo *<select v-model.number="form.grupo_id" @change="groupChanged"><option :value="0">Seleccione</option><option v-for="x in groups" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Subgrupo *<select v-model.number="form.subgrupo_id" :disabled="!form.grupo_id"><option :value="0">Seleccione</option><option v-for="x in subgroups" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label class="wide">Nombre *<input v-model.trim="form.nombre" maxlength="255"></label><label>Unidad de medida *<select v-model.number="form.unidad_id"><option :value="0">Seleccione</option><option v-for="x in units" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label class="check"><input v-model="form.uso_comun" type="checkbox"> Bien de uso común</label><p class="wide hint">Familia seleccionada: <b>{{selectedGroup?.familia||'—'}}</b></p></div><div v-else><div class="grid"><label>Stock mínimo<input v-model.number="form.stock_minimo" type="number" min="0" step="0.01"></label><label>Stock máximo<input v-model.number="form.stock_maximo" type="number" min="0" step="0.01"></label><label>Lote económico<input v-model.number="form.lote_economico" type="number" min="0" step="0.01"></label><label>Punto de reposición<input v-model.number="form.punto_reposicion" type="number" min="0" step="0.01"></label><label>Consumo promedio<input v-model.number="form.consumo_promedio" type="number" min="0" step="0.01" readonly></label></div><section class="photo"><div v-if="preview" class="preview"><img :src="preview" alt="Vista previa"><button type="button" @click="removePhoto">Eliminar imagen</button></div><div v-else class="placeholder">📷<span>Sin fotografía</span></div><label>Fotografía<input type="file" accept="image/jpeg,image/png,image/bmp" @change="choosePhoto"><small>JPEG, PNG o BMP. Recomendado: 800 × 800 px.</small></label></section></div><footer><button type="button" class="soft" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar ítem'}}</button></footer></form></div></div></template>
<style scoped>
